import { ChainTxApiClient } from "../clients/chain/apiClient/ChainTxApiClient";
import { TxRaw } from "../types/chain/tx";
import { TxRaw as ProtoTxRaw } from "../gen/cosmos/tx/v1beta1/tx";

const ENDPOINT = "sentry.chain.grpc.injective.network:443";

const FIXTURES: { name: string; description: string; hex: string }[] = [
  {
    name: "deposit",
    description: "1 INJ into subaccount ...0003",
    hex: "",
  },
  {
    name: "withdraw",
    description: "0.000001 INJ out of subaccount ...0003",
    hex: "",
  },
  {
    name: "transfer",
    description: "0.000001 INJ from subaccount ...0003 to ...0002",
    hex: "",
  },
  {
    name: "batch",
    description: "deposit + withdraw in one tx (2 messages)",
    hex: "",
  },
];

function hexToTxRaw(hex: string): TxRaw {
  return ProtoTxRaw.decode(Buffer.from(hex, "hex"));
}

async function main() {
  const tx = new ChainTxApiClient(ENDPOINT);
  let passed = 0;
  let failed = 0;

  for (const fixture of FIXTURES) {
    const txRaw = hexToTxRaw(fixture.hex);
    process.stdout.write(`${fixture.name.padEnd(10)} ${fixture.description.padEnd(46)} `);

    try {
      const res = await tx.simulate(txRaw);
      passed++;
      console.log(
        `PASS  gasUsed=${res.gasInfo?.gasUsed} gasWanted=${res.gasInfo?.gasWanted} events=${res.result?.events?.length ?? 0}`,
      );
    } catch (error: any) {
      failed++;
      console.log(`FAIL  ${String(error.details ?? error.message).slice(0, 80)}`);
    }
  }

  console.log(`\n${passed} passed, ${failed} failed`);
  process.exit(failed > 0 ? 1 : 0);
}

main();
